export const WALK_KEYS181=[['W A S D','Caminar'],['Mouse derecho + arrastrar','Mirar alrededor'],['Shift','Paso rápido'],['Ctrl','Agacharte mientras lo mantienes'],['C','Alternar agachado / de pie']];
export const WORK_KEYS181=[['E','Interactuar'],['F','Enfocar el trabajo actual'],['Tab','Abrir / cerrar la bolsa'],['Q','Guardar herramienta'],['1–9','Seleccionar herramienta'],['Esc','Soltar o cancelar']];
export function key181(e){return /^Key[WASDC]$/.test(e.code||'')?e.code.slice(3).toLowerCase():String(e.key||'').toLowerCase();}
export function installKeyHelp181(controller,canvas,doc,active,maintenance=false){if(!doc?.createElement||!canvas.parentElement)return;const root=doc.createElement('details');root.className='input181-help';root.hidden=!active();root.innerHTML='<summary>WASD · Mouse <kbd>H</kbd></summary><section><b>CONTROLES A PIE</b><dl>'+[...WALK_KEYS181,...(maintenance?WORK_KEYS181:[])].map(([key,action])=>'<div><dt>'+key+'</dt><dd>'+action+'</dd></div>').join('')+'</dl><button type="button" data-pad181>Mostrar botones en pantalla</button></section>';canvas.parentElement.append(root);const pad=()=>controller.pad180||controller.view.service128?.checklist179?.pad,toggle=root.querySelector('[data-pad181]');if(toggle)toggle.onclick=()=>{const p=pad();if(!p)return;const show=p.dataset.visible181!=='true';p.dataset.visible181=String(show);toggle.textContent=show?'Ocultar botones en pantalla':'Mostrar botones en pantalla';};const keyboard=maintenance?controller.view.dialog:doc;keyboard.addEventListener?.('keydown',e=>{if(!active()||e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||key181(e)!=='h')return;e.preventDefault();e.stopImmediatePropagation();root.open=!root.open;},true);controller.help181=root;return root;}
